"""Author-owned Hebrew educational content; writes src/data/course.json.
Topic order follows the public tables of contents for מסלולים חדשים 9–12.
No textbook problems or explanations are copied.
"""
import json
from pathlib import Path

chapters=[]
chapter=None

def C(cid, book, title, desc, accent, icon):
    global chapter
    chapter={'id':cid,'book':book,'title':title,'desc':desc,'accent':accent,'icon':icon,'lessons':[]}
    chapters.append(chapter)

def L(id,title,subtitle,objective,steps,example,answer,explain,gen,config=None,visual=None,tag='core'):
    o={'id':id,'book':chapter['book'],'chapter':chapter['id'],'title':title,'subtitle':subtitle,
       'objective':objective,'steps':steps.split('|'), 'worked':[{'prompt':example,'answer':str(answer),'explanation':explain}],
       'generator':gen,'tag':tag}
    if config: o['config']=config
    if visual: o['worked'][0]['visual']=visual
    chapter['lessons'].append(o)

